print('HISTORY COVERAGE')
for mode in ['train','eval']:
    total=mismatch=cross=0;affected=set();ids=set()
    for r in req:
        if r['mode']!=mode or r['phase']!='continuation':continue
        for i,(tid,p) in enumerate(zip(r['trajectory_ids'],r['expected_prompt_ids'])):
            total+=1;ids.add(tid)
            if p!=r['server_prompt_ids'][i//4]:mismatch+=1;affected.add(tid)
            if by[tid][0]['case_id']!=by[r['trajectory_ids'][(i//4)*4]][0]['case_id']:cross+=1
    print(mode,'continuation rows',total,'mismatched rows',mismatch,'affected trajectories',len(affected),'of',len(ids),'crosscase',cross)
